import android.content.Intent
import android.net.Uri
import android.os.Bundle
import android.util.Log
import android.widget.ImageView
import android.widget.LinearLayout
import androidx.activity.enableEdgeToEdge
import androidx.activity.result.contract.ActivityResultContracts
import androidx.appcompat.app.AlertDialog
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat
import com.bumptech.glide.request.RequestOptions
import com.google.firebase.auth.FirebaseAuth
import java.io.File
import java.io.FileOutputStream
import java.io.InputStream
import androidx.core.net.toUri
import androidx.core.content.edit
import com.yalantis.ucrop.UCrop
import androidx.core.content.FileProvider

class ActivityPerfilMaker : BaseActivity() {
    companion object {
        private const val prefsName = "perfil_prefs"
        private const val keyImageUri = "image_uri"
        private const val keyImagePath = "image_path"
    }

    private lateinit var userImage: ImageView

    // Helper to (re)configure the BottomNavigationView listener consistently
    private fun setupBottomNav(bottomNav: com.google.android.material.bottomnavigation.BottomNavigationView) {
        bottomNav.setOnItemSelectedListener { item ->
            try {
                when (item.itemId) {
                    R.id.action_home -> { startActivity(Intent(this, ActivityHomeComum::class.java)); true }
                    R.id.action_scan -> { startActivity(Intent(this, ActivityScanQR::class.java)); true }
                    R.id.action_favoritos -> { startActivity(Intent(this, ActivityFavoritos::class.java)); true }
                    R.id.action_config -> { /* already here */ true }
                    R.id.action_criar -> { startActivity(Intent(this, com.example.indoorar.ui.ActivityEditor::class.java)); true }
                    R.id.action_estatisticas -> { startActivity(Intent(this, ActivityEstatisticas::class.java)); true }
                    else -> false
                }
            } catch (e: Exception) {
                Log.e("PerfilMaker", "Erro ao tratar seleção do bottom nav", e)
                false
            }
        }
        // Select profile item after listener is set
        bottomNav.post { try { bottomNav.selectedItemId = R.id.action_config } catch (_: Exception) {} }
    }

    private fun saveImageToInternalStorage(uri: Uri): String? {
        return try {
            val inputStream: InputStream? = contentResolver.openInputStream(uri)
            val file = File(filesDir, "profile_image.jpg")
            val outputStream = FileOutputStream(file)
            inputStream?.copyTo(outputStream)
            inputStream?.close()
            outputStream.close()
            file.absolutePath
        } catch (e: Exception) {
            Log.e("PerfilMaker", "Erro ao salvar imagem", e)
            null
        }
    }

    private val cropImageLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) { result ->
        val data = result.data
        if (result.resultCode == RESULT_OK && data != null) {
            val resultUri = UCrop.getOutput(data)
            if (resultUri != null) {
                val imagePath = saveImageToInternalStorage(resultUri)
                if (imagePath != null) {
                    com.bumptech.glide.Glide.with(this)
                        .load(imagePath)
                        .apply(RequestOptions.circleCropTransform())
                        .placeholder(R.drawable.account_circle)
                        .error(R.drawable.account_circle)
                        .into(userImage)
                    val prefs = getSharedPreferences(prefsName, MODE_PRIVATE)
                    prefs.edit { putString(keyImagePath, imagePath).remove(keyImageUri) }
                } else {
                    userImage.setImageResource(R.drawable.account_circle)
                }
            } else {
                val err = UCrop.getError(data)
                if (err != null) Log.e("PerfilMaker", "UCrop error", err)
                userImage.setImageResource(R.drawable.account_circle)
            }
        } else if (result.data != null) {
            val err = UCrop.getError(result.data!!)
            if (err != null) Log.e("PerfilMaker", "UCrop RESULT_ERROR", err)
        }
    }

    private val pickImageLauncher = registerForActivityResult(ActivityResultContracts.GetContent()) { uri: Uri? ->
        uri?.let {
            try {
                val destinationFile = File(getExternalFilesDir(null), "cropped_profile_image.jpg")
                val destinationUri = FileProvider.getUriForFile(
                    this,
                    "$packageName.fileprovider",
                    destinationFile
                )
                val uCrop = UCrop.of(it, destinationUri)
                    .withAspectRatio(1f, 1f)
                    .withOptions(UCrop.Options().apply {
                        setCircleDimmedLayer(true)
                        setShowCropFrame(false)
                        setShowCropGrid(false)
                    })
                val intent = uCrop.getIntent(this).apply {
                    addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION)
                }
                val targetPkg = intent.component?.packageName
                    ?: intent.resolveActivity(packageManager)?.packageName
                if (!targetPkg.isNullOrBlank()) {
                    try { grantUriPermission(targetPkg, it, Intent.FLAG_GRANT_READ_URI_PERMISSION) } catch (_: Exception) {}
                    try { grantUriPermission(targetPkg, destinationUri, Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION) } catch (_: Exception) {}
                }
                cropImageLauncher.launch(intent)
            } catch (e: Exception) {
                Log.e("PerfilMaker", "Falha ao abrir UCrop, aplicando fallback", e)
                try {
                    val imagePath = saveImageToInternalStorage(it)
                    if (imagePath != null) {
                        com.bumptech.glide.Glide.with(this)
                            .load(imagePath)
                            .apply(RequestOptions.circleCropTransform())
                            .placeholder(R.drawable.account_circle)
                            .error(R.drawable.account_circle)
                            .into(userImage)
                        val prefs = getSharedPreferences(prefsName, MODE_PRIVATE)
                        prefs.edit { putString(keyImagePath, imagePath).remove(keyImageUri) }
                    } else {
                        userImage.setImageResource(R.drawable.account_circle)
                    }
                } catch (_: Exception) {
                    android.widget.Toast.makeText(this, "Erro ao processar imagem selecionada", android.widget.Toast.LENGTH_LONG).show()
                }
            }
        }
    }

    private val requestMediaImagesPermissionLauncher = registerForActivityResult(ActivityResultContracts.RequestPermission()) { isGranted ->
        if (isGranted) pickImageLauncher.launch("image/*")
        else android.widget.Toast.makeText(this, "Permissão para acessar imagens negada", android.widget.Toast.LENGTH_LONG).show()
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_perfil_maker)
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main)) { v, insets ->
            val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars())
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, 0)
            insets
        }

        val txtNomeUsuario = findViewById<android.widget.TextView>(R.id.txtNomeUsuario)
        val txtEmailUsuario = findViewById<android.widget.TextView>(R.id.txtEmailUsuario)
        userImage = findViewById(R.id.userImage)
        val prefs = getSharedPreferences(prefsName, MODE_PRIVATE)
        val savedPath = prefs.getString(keyImagePath, null)
        val savedUri = prefs.getString(keyImageUri, null)
        val user = FirebaseAuth.getInstance().currentUser
        if (user != null) {
            txtEmailUsuario.text = user.email ?: "Email não disponível"
            val db = com.google.firebase.firestore.FirebaseFirestore.getInstance()
            db.collection("usuarios").document(user.uid).get().addOnSuccessListener { doc ->
                val nome = doc.getString("nome") ?: "Nome não disponível"
                txtNomeUsuario.text = nome
            }.addOnFailureListener {
                txtNomeUsuario.text = "Nome não disponível"
            }
        } else {
            txtNomeUsuario.text = "Usuário não logado"
            txtEmailUsuario.text = "Usuário não logado"
        }

        if (savedPath != null) {
            Log.d("PerfilMaker", "Carregando imagem do caminho: $savedPath")
            com.bumptech.glide.Glide.with(this)
                .load(savedPath)
                .apply(RequestOptions.circleCropTransform())
                .placeholder(R.drawable.account_circle)
                .error(R.drawable.account_circle)
                .into(userImage)
        } else if (savedUri != null) {
            try {
                Log.d("PerfilMaker", "Tentando carregar imagem URI: $savedUri")
                com.bumptech.glide.Glide.with(this)
                    .load(savedUri.toUri())
                    .apply(RequestOptions.circleCropTransform())
                    .placeholder(R.drawable.account_circle)
                    .error(R.drawable.account_circle)
                    .into(userImage)
            } catch (_: Exception) {
                userImage.setImageResource(R.drawable.account_circle)
            }
        } else {
            userImage.setImageResource(R.drawable.account_circle)
        }

        userImage.setOnClickListener {
            val options = arrayOf("Remover foto de perfil", "Escolher da galeria")
            AlertDialog.Builder(this)
                .setTitle("Foto de perfil")
                .setItems(options) { dialog, which ->
                    when (which) {
                        0 -> {
                            val prefs = getSharedPreferences(prefsName, MODE_PRIVATE)
                            prefs.edit { remove(keyImagePath).remove(keyImageUri) }
                            userImage.setImageResource(R.drawable.account_circle)
                        }
                        1 -> {
                            if (android.os.Build.VERSION.SDK_INT >= 33) {
                                requestMediaImagesPermissionLauncher.launch(android.Manifest.permission.READ_MEDIA_IMAGES)
                            } else {
                                pickImageLauncher.launch("image/*")
                            }
                        }
                    }
                }
                .show()
        }

        val itemSair = findViewById<LinearLayout>(R.id.itemSair)
        itemSair.setOnClickListener {
            FirebaseAuth.getInstance().signOut()
            val intent = Intent(this, ActivityLogin::class.java)
            intent.flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK
            startActivity(intent)
            finish()
        }

        val itemConfiguracoes = findViewById<LinearLayout>(R.id.itemConfiguracoes)
        itemConfiguracoes?.setOnClickListener {
            startActivity(Intent(this, ActivityConfigConta::class.java))
        }
        val itemHistorico = findViewById<LinearLayout>(R.id.itemHistorico)
        itemHistorico?.setOnClickListener {
            android.widget.Toast.makeText(this, "Histórico - em desenvolvimento", android.widget.Toast.LENGTH_SHORT).show()
        }
        val itemCalendario = findViewById<LinearLayout>(R.id.itemCalendario)
        itemCalendario?.setOnClickListener {
            android.widget.Toast.makeText(this, "Estatísticas - em desenvolvimento", android.widget.Toast.LENGTH_SHORT).show()
        }
        val itemAjuda = findViewById<LinearLayout>(R.id.itemAjuda)
        itemAjuda?.setOnClickListener {
            android.widget.Toast.makeText(this, "Ajuda e Suporte - em desenvolvimento", android.widget.Toast.LENGTH_SHORT).show()
        }

        val bottomNav = findViewById<com.google.android.material.bottomnavigation.BottomNavigationView>(R.id.bottomNavPerfil)
        if (bottomNav != null) {
            bottomNav.menu.clear()
            bottomNav.inflateMenu(R.menu.bottom_nav_maker)
            // Ignore bottom system inset on the BottomNavigationView itself
            ViewCompat.setOnApplyWindowInsetsListener(bottomNav) { v, insets ->
                v.setPadding(v.paddingLeft, v.paddingTop, v.paddingRight, 0)
                insets
            }
            setupBottomNav(bottomNav)
        }
    }

    override fun onResume() {
        super.onResume()
        syncUserEmailToFirestore {
            val user = FirebaseAuth.getInstance().currentUser
            val emailAtual = user?.email ?: "Email não disponível"
            findViewById<android.widget.TextView>(R.id.txtEmailUsuario)?.text = emailAtual
        }
    }
}

package com.example.indoorar

import android.Manifest
import android.content.Intent
import android.content.pm.PackageManager
import android.os.Bundle
import android.widget.Button
import android.widget.Toast
import androidx.activity.result.contract.ActivityResultContracts
import androidx.camera.core.*
import androidx.camera.lifecycle.ProcessCameraProvider
import androidx.camera.view.PreviewView
import androidx.core.content.ContextCompat
import com.google.common.util.concurrent.ListenableFuture
import com.google.zxing.*
import com.google.zxing.common.HybridBinarizer
import android.content.res.ColorStateList
import androidx.core.graphics.toColorInt
import com.google.android.material.bottomnavigation.BottomNavigationView


class ActivityScanQR : BaseActivity() {

    private lateinit var previewView: PreviewView
    private lateinit var btnEscanear: Button
    private lateinit var cameraProviderFuture: ListenableFuture<ProcessCameraProvider>
    private var lastScanned: String? = null
    private var cameraBound = false

    // Hold references to release camera cleanly
    private var cameraProvider: ProcessCameraProvider? = null
    private var imageAnalysis: ImageAnalysis? = null

    // Prevent double navigation
    private var navigating = false

    private val requestPermission = registerForActivityResult(
        ActivityResultContracts.RequestPermission()
    ) { granted ->
        if (granted) startCamera()
        else Toast.makeText(this, "Permissão de câmera é necessária.", Toast.LENGTH_LONG).show()
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_scanqr)

        previewView = findViewById(R.id.previewView)
        btnEscanear = findViewById(R.id.btnEscanear)

        // Wire bottom navigation (conta comum) — layout now contains `bottomNavComum`
        findViewById<BottomNavigationView>(R.id.bottomNavComum)?.apply {
            selectedItemId = R.id.action_scan
            setOnItemSelectedListener { item ->
                if (this.selectedItemId == item.itemId) return@setOnItemSelectedListener true
                when (item.itemId) {
                    R.id.action_home -> { startActivity(Intent(this@ActivityScanQR, ActivityHomeComum::class.java)); true }
                    R.id.action_scan -> { true }
                    R.id.action_favoritos -> { startActivity(Intent(this@ActivityScanQR, ActivityFavoritos::class.java)); true }
                    R.id.action_config -> { startActivity(Intent(this@ActivityScanQR, ActivityPerfilComum::class.java)); true }
                    else -> false
                }
            }
        }

        // Estado inicial: desabilitado e cinza
        btnEscanear.isEnabled = false
        btnEscanear.text = "ESCANEAR"
        btnEscanear.backgroundTintList = ColorStateList.valueOf("#BDBDBD".toColorInt())
        btnEscanear.setOnClickListener {
            val value = lastScanned ?: return@setOnClickListener
            if (navigating) return@setOnClickListener
            navigating = true
            btnEscanear.isEnabled = false
            handleResult(value)
        }

        ensureCameraPermissionAndStart()
    }


    override fun onPause() {
        super.onPause()
        // Ensure camera is released as we leave
        stopCamera()
    }

    override fun onDestroy() {
        super.onDestroy()
        stopCamera()
    }

    private fun ensureCameraPermissionAndStart() {
        when {
            ContextCompat.checkSelfPermission(
                this, Manifest.permission.CAMERA
            ) == PackageManager.PERMISSION_GRANTED -> startCamera()

            shouldShowRequestPermissionRationale(Manifest.permission.CAMERA) -> {
                Toast.makeText(this, "Precisamos da câmera para ler o QR.", Toast.LENGTH_SHORT).show()
                requestPermission.launch(Manifest.permission.CAMERA)
            }

            else -> requestPermission.launch(Manifest.permission.CAMERA)
        }
    }

    @androidx.annotation.OptIn(ExperimentalGetImage::class)
    private fun startCamera() {
        if (cameraBound) return

        cameraProviderFuture = ProcessCameraProvider.getInstance(this)
        cameraProviderFuture.addListener({
            val provider = cameraProviderFuture.get()
            cameraProvider = provider

            val preview = Preview.Builder().build().also {
                it.surfaceProvider = previewView.surfaceProvider
            }

            val analysis = ImageAnalysis.Builder()
                .setBackpressureStrategy(ImageAnalysis.STRATEGY_KEEP_ONLY_LATEST)
                .build()
            imageAnalysis = analysis

            val reader = MultiFormatReader().apply {
                setHints(mapOf(
                    DecodeHintType.POSSIBLE_FORMATS to arrayListOf(BarcodeFormat.QR_CODE),
                    DecodeHintType.TRY_HARDER to true
                ))
            }

            analysis.setAnalyzer(ContextCompat.getMainExecutor(this)) { imageProxy ->
                val mediaImage = imageProxy.image
                if (mediaImage != null) {
                    val crop = imageProxy.cropRect
                    val source = ImageUtils.getLuminanceSourceFromImage(mediaImage, crop)
                    val bitmap = BinaryBitmap(HybridBinarizer(source))
                    try {
                        val result = reader.decode(bitmap)
                        if (result.text != lastScanned) {
                            lastScanned = result.text
                            // Update UI: enable and turn blue with ESCANEAR
                            btnEscanear.isEnabled = true
                            btnEscanear.text = "ESCANEAR"
                            btnEscanear.backgroundTintList = ColorStateList.valueOf("#32357A".toColorInt())
                        }
                    } catch (_: NotFoundException) {
                        // nada encontrado no frame
                    } catch (_: Exception) {
                        // qualquer outra exceção do ZXing
                    } finally {
                        reader.reset() // evita estado sujo entre frames
                        imageProxy.close()
                    }
                } else {
                    imageProxy.close()
                }
            }

            val cameraSelector = CameraSelector.DEFAULT_BACK_CAMERA
            try {
                provider.unbindAll()
                provider.bindToLifecycle(this, cameraSelector, preview, analysis)
                cameraBound = true
            } catch (e: Exception) {
                Toast.makeText(this, "Erro iniciando câmera: ${e.message}", Toast.LENGTH_LONG).show()
            }
        }, ContextCompat.getMainExecutor(this))
    }

    private fun stopCamera() {
        try { imageAnalysis?.clearAnalyzer() } catch (_: Exception) {}
        try {
            if (cameraProvider == null) {
                // Try to resolve from future if possible
                cameraProvider = try { cameraProviderFuture.get() } catch (_: Exception) { null }
            }
            cameraProvider?.unbindAll()
        } catch (_: Exception) {}
        cameraBound = false
    }

    private fun handleResult(value: String) {
        val returnResult = intent.getBooleanExtra("RETURN_RESULT", false)

        // Tenta extrair um mapId válido do QR (id puro, URL com /mapas/{id} ou ?mapId=)
        val mapId = extractMapIdFromQr(value)
        if (mapId == null) {
            // Falha em interpretar o QR
            Toast.makeText(this, "QR inválido", Toast.LENGTH_SHORT).show()
            navigating = false
            btnEscanear.isEnabled = true
            return
        }

        stopCamera()

        if (returnResult) {
            val intent = Intent()
            intent.putExtra("QR_VALUE", mapId)
            setResult(RESULT_OK, intent)
            finish()
        } else {
            val mapIntent = Intent(this, ActivityNavHud::class.java).apply {
                putExtra("MAP_ID", mapId)
            }
            startActivity(mapIntent)
            finish()
        }
    }

    private fun extractMapIdFromQr(raw: String): String? {
        val s = raw.trim()
        // Caso 1: já é um id simples (sem barra)
        if (!s.contains('/')) return s

        // Caso 2: URL com parâmetro ?mapId=XYZ
        run {
            val idx = s.indexOf("mapId=")
            if (idx >= 0) {
                val sub = s.substring(idx + 6)
                val end = listOf('&', '#', '?', '/').map { c -> sub.indexOf(c).takeIf { it >= 0 } ?: sub.length }.min()
                val id = sub.substring(0, end)
                if (id.isNotBlank()) return id
            }
        }

        // Caso 3: caminho contendo /mapas/{id}
        run {
            val token = "/mapas/"
            val idx = s.indexOf(token)
            if (idx >= 0) {
                val sub = s.substring(idx + token.length)
                val end = sub.indexOf('/')
                val id = if (end >= 0) sub.substring(0, end) else sub
                if (id.isNotBlank()) return id
            }
        }

        // Última tentativa: pega o último segmento da URL
        run {
            val parts = s.split('/').filter { it.isNotBlank() }
            if (parts.isNotEmpty()) {
                val tail = parts.last()
                if (tail.isNotBlank()) return tail
            }
        }

        return null
    }
}

package com.example.indoorar

import android.Manifest
import android.content.Intent
import android.content.pm.PackageManager
import android.os.Bundle
import android.widget.Button
import android.widget.Toast
import androidx.activity.result.contract.ActivityResultContracts
import androidx.camera.core.*
import androidx.camera.lifecycle.ProcessCameraProvider
import androidx.camera.view.PreviewView
import androidx.core.content.ContextCompat
import com.google.common.util.concurrent.ListenableFuture
import com.google.zxing.*
import com.google.zxing.common.HybridBinarizer
import android.content.res.ColorStateList
import androidx.core.graphics.toColorInt
import com.google.android.material.bottomnavigation.BottomNavigationView
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat


class ActivityScanQR : BaseActivity() {

    private lateinit var previewView: PreviewView
    private lateinit var btnEscanear: Button
    private lateinit var cameraProviderFuture: ListenableFuture<ProcessCameraProvider>
    private var lastScanned: String? = null
    private var cameraBound = false

    // Hold references to release camera cleanly
    private var cameraProvider: ProcessCameraProvider? = null
    private var imageAnalysis: ImageAnalysis? = null

    // Prevent double navigation
    private var navigating = false

    private val requestPermission = registerForActivityResult(
        ActivityResultContracts.RequestPermission()
    ) { granted ->
        if (granted) startCamera()
        else Toast.makeText(this, "Permissão de câmera é necessária.", Toast.LENGTH_LONG).show()
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_scanqr)

        // Aplicar insets: topo/laterais no root; não adicionar padding inferior
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main)) { v, insets ->
            val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars())
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, 0)
            insets
        }

        previewView = findViewById(R.id.previewView)
        btnEscanear = findViewById(R.id.btnEscanear)

        // Wire bottom navigation (conta comum) — layout now contains `bottomNavComum`
        findViewById<BottomNavigationView>(R.id.bottomNavComum)?.apply {
            // Evita padding inferior de insets na navbar para se manter colada no fundo
            ViewCompat.setOnApplyWindowInsetsListener(this) { v, insets ->
                v.setPadding(v.paddingLeft, v.paddingTop, v.paddingRight, 0)
                insets
            }
            selectedItemId = R.id.action_scan
            setOnItemSelectedListener { item ->
                if (this.selectedItemId == item.itemId) return@setOnItemSelectedListener true
                when (item.itemId) {
                    R.id.action_home -> { startActivity(Intent(this@ActivityScanQR, ActivityHomeComum::class.java)); true }
                    R.id.action_scan -> { true }
                    R.id.action_favoritos -> { startActivity(Intent(this@ActivityScanQR, ActivityFavoritos::class.java)); true }
                    R.id.action_config -> { startActivity(Intent(this@ActivityScanQR, ActivityPerfilComum::class.java)); true }
                    else -> false
                }
            }
        }

        // Estado inicial: desabilitado e cinza
        btnEscanear.isEnabled = false
        btnEscanear.text = "ESCANEAR"
        btnEscanear.backgroundTintList = ColorStateList.valueOf("#BDBDBD".toColorInt())
        btnEscanear.setOnClickListener {
            val value = lastScanned ?: return@setOnClickListener
            if (navigating) return@setOnClickListener
            navigating = true
            btnEscanear.isEnabled = false
            handleResult(value)
        }

        ensureCameraPermissionAndStart()
    }


    override fun onPause() {
        super.onPause()
        // Ensure camera is released as we leave
        stopCamera()
    }

    override fun onDestroy() {
        super.onDestroy()
        stopCamera()
    }

    private fun ensureCameraPermissionAndStart() {
        when {
            ContextCompat.checkSelfPermission(
                this, Manifest.permission.CAMERA
            ) == PackageManager.PERMISSION_GRANTED -> startCamera()

            shouldShowRequestPermissionRationale(Manifest.permission.CAMERA) -> {
                Toast.makeText(this, "Precisamos da câmera para ler o QR.", Toast.LENGTH_SHORT).show()
                requestPermission.launch(Manifest.permission.CAMERA)
            }

            else -> requestPermission.launch(Manifest.permission.CAMERA)
        }
    }

    @androidx.annotation.OptIn(ExperimentalGetImage::class)
    private fun startCamera() {
        if (cameraBound) return

        cameraProviderFuture = ProcessCameraProvider.getInstance(this)
        cameraProviderFuture.addListener({
            val provider = cameraProviderFuture.get()
            cameraProvider = provider

            val preview = Preview.Builder().build().also {
                it.surfaceProvider = previewView.surfaceProvider
            }

            val analysis = ImageAnalysis.Builder()
                .setBackpressureStrategy(ImageAnalysis.STRATEGY_KEEP_ONLY_LATEST)
                .build()
            imageAnalysis = analysis

            val reader = MultiFormatReader().apply {
                setHints(mapOf(
                    DecodeHintType.POSSIBLE_FORMATS to arrayListOf(BarcodeFormat.QR_CODE),
                    DecodeHintType.TRY_HARDER to true
                ))
            }

            analysis.setAnalyzer(ContextCompat.getMainExecutor(this)) { imageProxy ->
                try {
                    val mediaImage = imageProxy.image ?: return@setAnalyzer
                    val crop = imageProxy.cropRect
                    val source = try {
                        ImageUtils.getLuminanceSourceFromImage(mediaImage, crop)
                    } catch (_: Exception) {
                        // Fallback: usa frame inteiro se recorte falhar
                        android.graphics.Rect(0, 0, mediaImage.width, mediaImage.height).let { full ->
                            ImageUtils.getLuminanceSourceFromImage(mediaImage, full)
                        }
                    }
                    val bitmap = BinaryBitmap(HybridBinarizer(source))
                    val result = reader.decode(bitmap)
                    if (result.text != lastScanned) {
                        lastScanned = result.text
                        btnEscanear.isEnabled = true
                        btnEscanear.text = "ESCANEAR"
                        btnEscanear.backgroundTintList = ColorStateList.valueOf("#32357A".toColorInt())
                    }
                } catch (_: NotFoundException) {
                    // Nada encontrado no frame
                } catch (_: Exception) {
                    // Ignora qualquer erro do pipeline de leitura para evitar crash
                } finally {
                    try { reader.reset() } catch (_: Exception) {}
                    imageProxy.close()
                }
            }

            val cameraSelector = CameraSelector.DEFAULT_BACK_CAMERA
            try {
                provider.unbindAll()
                provider.bindToLifecycle(this, cameraSelector, preview, analysis)
                cameraBound = true
            } catch (e: Exception) {
                Toast.makeText(this, "Erro iniciando câmera: ${e.message}", Toast.LENGTH_LONG).show()
            }
        }, ContextCompat.getMainExecutor(this))
    }

    private fun stopCamera() {
        try { imageAnalysis?.clearAnalyzer() } catch (_: Exception) {}
        try {
            if (cameraProvider == null) {
                // Try to resolve from future if possible
                cameraProvider = try { cameraProviderFuture.get() } catch (_: Exception) { null }
            }
            cameraProvider?.unbindAll()
        } catch (_: Exception) {}
        cameraBound = false
    }

    private fun handleResult(value: String) {
        val returnResult = intent.getBooleanExtra("RETURN_RESULT", false)

        // Tenta extrair um mapId válido do QR (id puro, URL com /mapas/{id} ou ?mapId=)
        val mapId = extractMapIdFromQr(value)
        if (mapId == null) {
            // Falha em interpretar o QR
            Toast.makeText(this, "QR inválido", Toast.LENGTH_SHORT).show()
            navigating = false
            btnEscanear.isEnabled = true
            return
        }

        stopCamera()

        if (returnResult) {
            val intent = Intent()
            intent.putExtra("QR_VALUE", mapId)
            setResult(RESULT_OK, intent)
            finish()
        } else {
            val mapIntent = Intent(this, ActivityNavHud::class.java).apply {
                putExtra("MAP_ID", mapId)
            }
            startActivity(mapIntent)
            finish()
        }
    }

    private fun extractMapIdFromQr(raw: String): String? {
        val s = raw.trim()
        // Caso 1: já é um id simples (sem barra)
        if (!s.contains('/')) return s

        // Caso 2: URL com parâmetro ?mapId=XYZ
        run {
            val idx = s.indexOf("mapId=")
            if (idx >= 0) {
                val sub = s.substring(idx + 6)
                val end = listOf('&', '#', '?', '/').map { c -> sub.indexOf(c).takeIf { it >= 0 } ?: sub.length }.min()
                val id = sub.substring(0, end)
                if (id.isNotBlank()) return id
            }
        }

        // Caso 3: caminho contendo /mapas/{id}
        run {
            val token = "/mapas/"
            val idx = s.indexOf(token)
            if (idx >= 0) {
                val sub = s.substring(idx + token.length)
                val end = sub.indexOf('/')
                val id = if (end >= 0) sub.substring(0, end) else sub
                if (id.isNotBlank()) return id
            }
        }

        // Última tentativa: pega o último segmento da URL
        run {
            val parts = s.split('/').filter { it.isNotBlank() }
            if (parts.isNotEmpty()) {
                val tail = parts.last()
                if (tail.isNotBlank()) return tail
            }
        }

        return null
    }
}

package com.example.indoorar

import android.graphics.Color
import android.os.Bundle
import android.os.Handler
import android.os.Looper
import android.view.View
import android.view.inputmethod.InputMethodManager
import androidx.appcompat.app.AppCompatActivity
import androidx.core.graphics.toColorInt
import androidx.core.view.*
import com.google.android.material.snackbar.Snackbar
import com.google.firebase.auth.FirebaseAuth
import com.google.firebase.firestore.FirebaseFirestore
import com.google.firebase.firestore.SetOptions
import android.util.Log

open class BaseActivity : AppCompatActivity() {

    private lateinit var insetsController: WindowInsetsControllerCompat
    private val handler = Handler(Looper.getMainLooper())
    private val hideDelay: Long = 2000 // 2 segundos

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setupUltimateFullScreen()
    }

    private fun setupUltimateFullScreen() {
        WindowCompat.setDecorFitsSystemWindows(window, false)
        insetsController = WindowInsetsControllerCompat(window, window.decorView)
        insetsController.systemBarsBehavior =
            WindowInsetsControllerCompat.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE

        hideSystemBars()

        window.decorView.setOnApplyWindowInsetsListener { _, insets ->
            val compatInsets = WindowInsetsCompat.toWindowInsetsCompat(insets)
            val systemBarsVisible = compatInsets.isVisible(WindowInsetsCompat.Type.systemBars())

            if (systemBarsVisible) {
                handler.removeCallbacksAndMessages(null)
                handler.postDelayed({ hideSystemBars() }, hideDelay)
            }
            insets
        }

        window.decorView.addOnLayoutChangeListener { _, _, _, _, _, _, _, _, _ ->
            hideSystemBars()
        }
    }

    private fun hideSystemBars() {
        insetsController.hide(WindowInsetsCompat.Type.systemBars())
    }

    override fun onDestroy() {
        super.onDestroy()
        handler.removeCallbacksAndMessages(null)
    }

    fun hideKeyboard() {
        val view = currentFocus
        if (view != null) {
            val imm = getSystemService(INPUT_METHOD_SERVICE) as InputMethodManager
            imm.hideSoftInputFromWindow(view.windowToken, 0)
        }
    }

    fun showSnackbar(msg: String, anchorView: View? = null) {
        hideKeyboard() // fecha teclado antes de mostrar uma mensagem

        val rootView = findViewById<View>(android.R.id.content)
        val snackbar = Snackbar.make(rootView, msg, Snackbar.LENGTH_SHORT)
        snackbar.setTextColor(Color.WHITE)
        snackbar.setBackgroundTint("#32357A".toColorInt())

        // Se passar um anchorView, a snackbar vai aparecer acima dela
        anchorView?.let { snackbar.setAnchorView(it) }

        snackbar.show()
    }

    // Sincroniza o e-mail do usuário do Auth com o documento do Firestore após alterações (como verificação de novo e-mail)
    fun syncUserEmailToFirestore(onDone: ((Boolean) -> Unit)? = null) {
        val user = FirebaseAuth.getInstance().currentUser
        if (user == null) {
            onDone?.invoke(false)
            return
        }
        user.reload()
            .addOnSuccessListener {
                val emailAtual = user.email
                if (emailAtual.isNullOrEmpty()) {
                    onDone?.invoke(false)
                    return@addOnSuccessListener
                }
                val db = FirebaseFirestore.getInstance()
                val docRef = db.collection("usuarios").document(user.uid)
                docRef.get()
                    .addOnSuccessListener { doc ->
                        val precisaAtualizar = !doc.exists() || doc.getString("email") != emailAtual
                        if (!precisaAtualizar) {
                            onDone?.invoke(true)
                            return@addOnSuccessListener
                        }
                        docRef.set(mapOf("email" to emailAtual), SetOptions.merge())
                            .addOnSuccessListener {
                                Log.d("BaseActivity", "Email sincronizado no Firestore: $emailAtual")
                                onDone?.invoke(true)
                            }
                            .addOnFailureListener { ex ->
                                Log.w("BaseActivity", "Falha ao sincronizar email no Firestore", ex)
                                onDone?.invoke(false)
                            }
                    }
                    .addOnFailureListener { ex ->
                        Log.w("BaseActivity", "Falha ao buscar documento do usuário para sincronizar", ex)
                        onDone?.invoke(false)
                    }
            }
            .addOnFailureListener { ex ->
                Log.w("BaseActivity", "Falha ao recarregar usuário antes de sincronizar email", ex)
                onDone?.invoke(false)
            }
    }
}

package com.example.indoorar

import android.content.ComponentCallbacks
import android.content.res.Configuration
import android.graphics.Color
import android.os.Bundle
import android.os.Handler
import android.os.Looper
import android.view.View
import android.view.inputmethod.InputMethodManager
import androidx.appcompat.app.AppCompatActivity
import androidx.core.graphics.toColorInt
import androidx.core.view.*
import com.google.android.material.snackbar.Snackbar
import com.google.firebase.auth.FirebaseAuth
import com.google.firebase.firestore.FirebaseFirestore
import com.google.firebase.firestore.SetOptions
import android.util.Log
import kotlin.math.min

open class BaseActivity : AppCompatActivity() {

    private lateinit var insetsController: WindowInsetsControllerCompat
    private val handler = Handler(Looper.getMainLooper())
    private val hideDelay: Long = 2000 // 2 segundos

    // --- Uniform density support (Toutiao-like adaptation) ---
    companion object {
        // Keep original scaledDensity so we can respect user font scale moderately
        private var nonCompatScaledDensity: Float = 0f
        private var densityApplied = false
    }

    // Allow child activities to customize their design width if necessary
    protected open fun designWidthDp(): Float = 360f

    override fun attachBaseContext(newBase: android.content.Context) {
        // Clamp extreme font scales to avoid layout breakage while still respecting accessibility
        val cfg = newBase.resources.configuration
        val clamped = cfg.fontScale.coerceIn(0.85f, 1.15f)
        if (clamped != cfg.fontScale) {
            val newCfg = Configuration(cfg)
            newCfg.fontScale = clamped
            val wrapped = newBase.createConfigurationContext(newCfg)
            super.attachBaseContext(wrapped)
        } else {
            super.attachBaseContext(newBase)
        }
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        // Apply uniform density before view inflation/theme adjustments that depend on metrics
        applyUniformDensity(designWidthDp = designWidthDp())
        super.onCreate(savedInstanceState)
        setupUltimateFullScreen()
    }

    private fun setupUltimateFullScreen() {
        WindowCompat.setDecorFitsSystemWindows(window, false)
        val controller = WindowInsetsControllerCompat(window, window.decorView)
        insetsController = controller
        controller.systemBarsBehavior =
            WindowInsetsControllerCompat.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE

        hideSystemBars()

        window.decorView.setOnApplyWindowInsetsListener { _, insets ->
            val compatInsets = WindowInsetsCompat.toWindowInsetsCompat(insets)
            val systemBarsVisible = compatInsets.isVisible(WindowInsetsCompat.Type.systemBars())

            if (systemBarsVisible) {
                handler.removeCallbacksAndMessages(null)
                handler.postDelayed({ hideSystemBars() }, hideDelay)
            }
            insets
        }

        window.decorView.addOnLayoutChangeListener { _, _, _, _, _, _, _, _, _ ->
            hideSystemBars()
        }
    }

    private fun hideSystemBars() {
        insetsController.hide(WindowInsetsCompat.Type.systemBars())
    }

    override fun onDestroy() {
        super.onDestroy()
        handler.removeCallbacksAndMessages(null)
    }

    // Apply a process/activity density based on a reference design width to normalize UI across devices
    private fun applyUniformDensity(designWidthDp: Float) {
        val app = application ?: return
        val appDm = app.resources.displayMetrics

        if (nonCompatScaledDensity == 0f) {
            nonCompatScaledDensity = appDm.scaledDensity
            // Keep scaledDensity updated if user changes font size at runtime
            app.registerComponentCallbacks(object : ComponentCallbacks {
                override fun onConfigurationChanged(newConfig: Configuration) {
                    if (newConfig.fontScale > 0) {
                        nonCompatScaledDensity = app.resources.displayMetrics.scaledDensity
                    }
                }
                override fun onLowMemory() { /* no-op */ }
            })
        }

        val shortestSidePx = min(appDm.widthPixels, appDm.heightPixels)
        if (shortestSidePx == 0) return

        val targetDensity = shortestSidePx / designWidthDp
        val targetScaledDensity = targetDensity * (nonCompatScaledDensity / appDm.density)
        val targetDensityDpi = (160 * targetDensity).toInt()

        // Apply to app metrics (affects most inflations, including third-party libs)
        if (!densityApplied || appDm.density != targetDensity) {
            appDm.density = targetDensity
            appDm.scaledDensity = targetScaledDensity
            appDm.densityDpi = targetDensityDpi
            densityApplied = true
        }

        // Apply to this activity's metrics as well
        val actDm = this.resources.displayMetrics
        actDm.density = targetDensity
        actDm.scaledDensity = targetScaledDensity
        actDm.densityDpi = targetDensityDpi
    }

    fun hideKeyboard() {
        val view = currentFocus
        val token = view?.windowToken
        if (token != null) {
            val imm = getSystemService(INPUT_METHOD_SERVICE) as InputMethodManager
            imm.hideSoftInputFromWindow(token, 0)
        }
    }

    fun showSnackbar(msg: String, anchorView: View? = null) {
        hideKeyboard() // fecha teclado antes de mostrar uma mensagem

        val rootView = findViewById<View>(android.R.id.content)
        val snackbar = Snackbar.make(rootView, msg, Snackbar.LENGTH_SHORT)
        snackbar.setTextColor(Color.WHITE)
        snackbar.setBackgroundTint("#32357A".toColorInt())

        // Se passar um anchorView, a snackbar vai aparecer acima dela
        anchorView?.let { snackbar.setAnchorView(it) }

        snackbar.show()
    }

    // Sincroniza o e-mail do usuário do Auth com o documento do Firestore após alterações (como verificação de novo e-mail)
    fun syncUserEmailToFirestore(onDone: ((Boolean) -> Unit)? = null) {
        val user = FirebaseAuth.getInstance().currentUser
        if (user == null) {
            onDone?.invoke(false)
            return
        }
        user.reload()
            .addOnSuccessListener {
                val emailAtual = user.email
                if (emailAtual.isNullOrEmpty()) {
                    onDone?.invoke(false)
                    return@addOnSuccessListener
                }
                val db = FirebaseFirestore.getInstance()
                val docRef = db.collection("usuarios").document(user.uid)
                docRef.get()
                    .addOnSuccessListener { doc ->
                        val precisaAtualizar = !doc.exists() || doc.getString("email") != emailAtual
                        if (!precisaAtualizar) {
                            onDone?.invoke(true)
                            return@addOnSuccessListener
                        }
                        docRef.set(mapOf("email" to emailAtual), SetOptions.merge())
                            .addOnSuccessListener {
                                Log.d("BaseActivity", "Email sincronizado no Firestore: $emailAtual")
                                onDone?.invoke(true)
                            }
                            .addOnFailureListener { ex ->
                                Log.w("BaseActivity", "Falha ao sincronizar email no Firestore", ex)
                                onDone?.invoke(false)
                            }
                    }
                    .addOnFailureListener { ex ->
                        Log.w("BaseActivity", "Falha ao buscar documento do usuário para sincronizar", ex)
                        onDone?.invoke(false)
                    }
            }
            .addOnFailureListener { ex ->
                Log.w("BaseActivity", "Falha ao recarregar usuário antes de sincronizar email", ex)
                onDone?.invoke(false)
            }
    }
}

package com.example.indoorar.ui.editor

import android.app.Activity
import android.view.KeyEvent
import android.view.View
import android.view.inputmethod.EditorInfo
import android.widget.EditText
import androidx.core.graphics.toColorInt
import com.example.indoorar.R
import com.example.indoorar.ui.Action
import java.util.Locale
import java.util.WeakHashMap
import com.google.android.material.switchmaterial.SwitchMaterial
import android.widget.ImageButton
import android.widget.TextView
import android.widget.SeekBar

class AttributePanelController(
    activity: Activity,
    private val editor: MapEditorView
) : MapEditorView.OnShapeSelectionListener {

    private data class Meta(
        var nome: String = "",
        var tipo: String = "",
        var corHex: String = "#D9D9D9"
    )

    private val metaStore = WeakHashMap<Action, Meta>()
    private var isProgrammatic = false

    private val painel = activity.findViewById<View>(R.id.painelAtributos)
    private val edtNome = activity.findViewById<EditText>(R.id.inputNome)
    private val edtPosX = activity.findViewById<EditText>(R.id.inputX)
    private val edtPosY = activity.findViewById<EditText>(R.id.inputY)
    private val edtWidth = activity.findViewById<EditText>(R.id.inputWidth)
    private val edtHeight = activity.findViewById<EditText>(R.id.inputHeight)

    private val rotationBar = activity.findViewById<SeekBar>(R.id.rotationSeekBar)
    private val rotationLabel = activity.findViewById<TextView>(R.id.rotationLabel)

    private val layoutStartQR = activity.findViewById<View>(R.id.layoutStartQR)
    private val switchIsStartQR = activity.findViewById<SwitchMaterial>(R.id.switchIsStartQR)
    private val layoutIsWalkable = activity.findViewById<View>(R.id.layoutIsWalkable)
    private val checkboxIsWalkable = activity.findViewById<android.widget.CheckBox>(R.id.checkboxIsWalkable)

    init {
        editor.selectionListener = this
        painel.visibility = View.GONE
        // Keep attribute panel always on top of other views
        painel.bringToFront()
        try { painel.elevation = 1000f } catch (_: Throwable) {}
        layoutStartQR?.visibility = View.GONE
        layoutIsWalkable?.visibility = View.GONE
        setupFieldHandlers()
        setupSwitch()
        setupWalkableCheckbox()
        setupRotation()
    }

    private fun setupSwitch() {
        switchIsStartQR?.setOnCheckedChangeListener { _, isChecked ->
            if (isProgrammatic) return@setOnCheckedChangeListener
            val poi = editor.actions.firstOrNull { it is Action.Poi && it.selected } as? Action.Poi
            poi?.isStartQR = isChecked
        }
    }

    private fun setupWalkableCheckbox() {
        checkboxIsWalkable?.setOnCheckedChangeListener { _, isChecked ->
            if (isProgrammatic) return@setOnCheckedChangeListener
            val shape = editor.actions.firstOrNull { it is Action.Shape && it.selected } as? Action.Shape
            shape?.let {
                it.isWalkable = isChecked
                // Ajusta cor base automaticamente conforme estilo definido
                if (isChecked) {
                    // Caminho walkable escuro
                    it.fillColor = "#1F2023".toColorInt()
                } else {
                    // Sala clara
                    it.fillColor = "#ECECEC".toColorInt()
                }
                // Não atualiza nenhum campo de cor no painel (seletor removido)
                editor.invalidate()
            }
        }
    }

    private fun setRotationLabel(value: Int) {
        rotationLabel?.text = "$value°"
    }

    private fun setRotationLabelFromProgress() {
        val v = rotationBar?.progress ?: 0
        rotationLabel?.text = "$v°"
    }

    private fun setupRotation() {
        rotationBar?.max = 360
        rotationBar?.setOnSeekBarChangeListener(object : SeekBar.OnSeekBarChangeListener {
            override fun onProgressChanged(seekBar: SeekBar?, progress: Int, fromUser: Boolean) {
                setRotationLabel(progress)
                if (!fromUser || isProgrammatic) return
                val obj = editor.actions.firstOrNull { (it is Action.Shape && it.selected) || (it is Action.Poi && it.selected) }
                when (obj) {
                    is Action.Shape -> { obj.rotation = progress.toFloat(); editor.invalidate() }
                    is Action.Poi -> { obj.rotation = progress.toFloat(); editor.invalidate() }
                    else -> {}
                }
            }
            override fun onStartTrackingTouch(seekBar: SeekBar?) {}
            override fun onStopTrackingTouch(seekBar: SeekBar?) {}
        })
    }

    // ===== MapEditorView callbacks =====
    override fun onShapeSelected(props: ShapeProps) {
        val obj = editor.actions.firstOrNull { (it is Action.Shape && it.selected) || (it is Action.Poi && it.selected) }
            ?: return
        val meta = metaStore.getOrPut(obj) {
            Meta(
                nome = when (obj) {
                    is Action.Shape -> obj.nome
                    else -> ""
                },
                corHex = if (obj is Action.Shape) String.format("#%06X", (0xFFFFFF and obj.fillColor)) else "#D9D9D9"
            )
        }

        isProgrammatic = true
        edtNome.setText(meta.nome)
        // Não exibe/atualiza campo de cor
        // Posição agora exibida em metros
        edtPosX.setText(fmt(editor.pxToMeters(props.x)))
        edtPosY.setText(fmt(editor.pxToMeters(props.y)))
        // Largura/altura exibidas em metros
        edtWidth.setText(fmt(editor.pxToMeters(props.width)))
        edtHeight.setText(fmt(editor.pxToMeters(props.height)))
        // Rotação
        rotationBar?.progress = props.rotation.toInt().coerceIn(0, rotationBar.max)
        setRotationLabelFromProgress()

        // Mostrar/ocultar seções conforme o tipo selecionado
        when (obj) {
            is Action.Poi -> {
                layoutStartQR?.visibility = View.VISIBLE
                switchIsStartQR?.isChecked = obj.isStartQR
                layoutIsWalkable?.visibility = View.GONE
                // Oculta campo de nome para POI
                edtNome?.visibility = View.GONE
            }
            is Action.Shape -> {
                layoutIsWalkable?.visibility = View.VISIBLE
                checkboxIsWalkable?.isChecked = obj.isWalkable
                layoutStartQR?.visibility = View.GONE
                // Exibe nome para Shape
                edtNome?.visibility = View.VISIBLE
            }
            else -> {
                layoutStartQR?.visibility = View.GONE
                layoutIsWalkable?.visibility = View.GONE
                edtNome?.visibility = View.GONE
            }
        }

        // Não atualiza preview de cor
        painel.visibility = View.VISIBLE
        // Reassert Z-order when showing
        painel.bringToFront()
        try { painel.elevation = 1000f } catch (_: Throwable) {}
        isProgrammatic = false
    }

    override fun onShapeDeselected() {
        painel.visibility = View.GONE
        layoutStartQR?.visibility = View.GONE
        layoutIsWalkable?.visibility = View.GONE
    }

    // ===== Field handlers =====
    private fun setupFieldHandlers() {
        applyOnEdit(edtPosX) { pushPosition() }
        applyOnEdit(edtPosY) { pushPosition() }
        applyOnEdit(edtWidth) { pushSize() }
        applyOnEdit(edtHeight) { pushSize() }
        applyOnEdit(edtNome) { saveMeta() }
        // Removido: applyOnEdit(edtCor) pois seletor/edição de cor foi desativado
    }

    private fun pushPosition() {
        if (isProgrammatic) return
        val obj = editor.actions.firstOrNull { (it is Action.Shape && it.selected) || (it is Action.Poi && it.selected) } ?: return

        // Entradas em metros -> converter para pixels
        val xMeters = edtPosX.text.toString().toFloatOrNull()
        val yMeters = edtPosY.text.toString().toFloatOrNull()
        val xPx = xMeters?.let { editor.metersToPx(it) }
        val yPx = yMeters?.let { editor.metersToPx(it) }

        when(obj) {
            is Action.Shape -> {
                val width = obj.end.x - obj.start.x
                val height = obj.end.y - obj.start.y
                if (xPx != null) obj.start.x = xPx
                if (yPx != null) obj.start.y = yPx
                obj.end.x = obj.start.x + width
                obj.end.y = obj.start.y + height
            }
            is Action.Poi -> {
                if (xPx != null) obj.x = xPx
                if (yPx != null) obj.y = yPx
            }
            is Action.BrushStroke -> {}
            is Action.Text -> {}
        }
        editor.invalidate()
    }

    private fun pushSize() {
        if (isProgrammatic) return
        val obj = editor.actions.firstOrNull { (it is Action.Shape && it.selected) || (it is Action.Poi && it.selected) } ?: return

        // Entradas são em metros; converter para pixels
        val wMeters = edtWidth.text.toString().toFloatOrNull()
        val hMeters = edtHeight.text.toString().toFloatOrNull()
        val wPx = wMeters?.let { editor.metersToPx(it) }
        val hPx = hMeters?.let { editor.metersToPx(it) }

        when(obj) {
            is Action.Shape -> {
                obj.end.x = obj.start.x + (wPx ?: (obj.end.x - obj.start.x))
                obj.end.y = obj.start.y + (hPx ?: (obj.end.y - obj.start.y))
            }
            is Action.Poi -> {
                obj.width = wPx ?: obj.width
                obj.height = hPx ?: obj.height
            }
            is Action.BrushStroke -> {} // nada
            is Action.Text -> {}
        }
        editor.invalidate()
    }

    private fun saveMeta() {
        if (isProgrammatic) return
        val obj = editor.actions.firstOrNull { (it is Action.Shape && it.selected) || (it is Action.Poi && it.selected) } ?: return
        val m = metaStore.getOrPut(obj) { Meta() }
        m.nome = edtNome.text.toString()
        // Não salva mais hex manual do painel (seletor removido)
        // m.corHex = edtCor.text.toString().ifBlank { "#D9D9D9" }
        when (obj) {
            is Action.Shape -> { obj.nome = m.nome }
            is Action.Poi -> { /* POI não possui nome/descrição */ }
            else -> {}
        }
    }

    private fun fmt(v: Float): String {
        return if (v % 1.0 == 0.0) v.toInt().toString()
        else String.format(Locale.US, "%.2f", v)
    }

    private fun applyOnEdit(edit: EditText, action: () -> Unit) {
        edit.imeOptions = EditorInfo.IME_ACTION_DONE
        edit.isSingleLine = true

        edit.setOnFocusChangeListener { _, hasFocus ->
            if (!hasFocus && !isProgrammatic) action()
        }
        edit.setOnEditorActionListener { v, actionId, event ->
            val imeDone = actionId == EditorInfo.IME_ACTION_DONE ||
                    (event?.keyCode == KeyEvent.KEYCODE_ENTER && event.action == KeyEvent.ACTION_UP)
            if (imeDone && !isProgrammatic) {
                action()
                val imm = v.context.getSystemService(android.content.Context.INPUT_METHOD_SERVICE) as android.view.inputmethod.InputMethodManager
                imm.hideSoftInputFromWindow(v.windowToken, 0)
                v.clearFocus()
                true
            } else false
        }
    }
}

package com.example.indoorar.ui.editor

import android.app.Activity
import android.view.KeyEvent
import android.view.View
import android.view.inputmethod.EditorInfo
import android.widget.EditText
import androidx.core.graphics.toColorInt
import com.example.indoorar.R
import com.example.indoorar.ui.Action
import java.util.Locale
import java.util.WeakHashMap
import com.google.android.material.switchmaterial.SwitchMaterial
import android.widget.ImageButton
import android.widget.TextView
import android.widget.SeekBar

class AttributePanelController(
    activity: Activity,
    private val editor: MapEditorView
) : MapEditorView.OnShapeSelectionListener {

    private data class Meta(
        var nome: String = "",
        var tipo: String = "",
        var corHex: String = "#D9D9D9"
    )

    private val metaStore = WeakHashMap<Action, Meta>()
    private var isProgrammatic = false

    private val painel = activity.findViewById<View>(R.id.painelAtributos)
    private val edtNome = activity.findViewById<EditText>(R.id.inputNome)
    private val edtPosX = activity.findViewById<EditText>(R.id.inputX)
    private val edtPosY = activity.findViewById<EditText>(R.id.inputY)
    private val edtWidth = activity.findViewById<EditText>(R.id.inputWidth)
    private val edtHeight = activity.findViewById<EditText>(R.id.inputHeight)

    private val rotationBar = activity.findViewById<SeekBar>(R.id.rotationSeekBar)
    private val rotationLabel = activity.findViewById<TextView>(R.id.rotationLabel)

    private val layoutStartQR = activity.findViewById<View>(R.id.layoutStartQR)
    private val switchIsStartQR = activity.findViewById<SwitchMaterial>(R.id.switchIsStartQR)
    private val layoutIsWalkable = activity.findViewById<View>(R.id.layoutIsWalkable)
    private val checkboxIsWalkable = activity.findViewById<android.widget.CheckBox>(R.id.checkboxIsWalkable)

    init {
        editor.selectionListener = this
        painel.visibility = View.GONE
        // Keep attribute panel always on top of other views
        painel.bringToFront()
        try { painel.elevation = 1000f } catch (_: Throwable) {}
        layoutStartQR?.visibility = View.GONE
        layoutIsWalkable?.visibility = View.GONE
        setupFieldHandlers()
        setupSwitch()
        setupWalkableCheckbox()
        setupRotation()
    }

    private fun setupSwitch() {
        switchIsStartQR?.setOnCheckedChangeListener { _, isChecked ->
            if (isProgrammatic) return@setOnCheckedChangeListener
            val poi = editor.actions.firstOrNull { it is Action.Poi && it.selected } as? Action.Poi
            poi?.isStartQR = isChecked
        }
    }

    private fun setupWalkableCheckbox() {
        checkboxIsWalkable?.setOnCheckedChangeListener { _, isChecked ->
            if (isProgrammatic) return@setOnCheckedChangeListener
            val shape = editor.actions.firstOrNull { it is Action.Shape && it.selected } as? Action.Shape
            shape?.let {
                it.isWalkable = isChecked
                // Ajusta cor base automaticamente conforme estilo definido
                if (isChecked) {
                    // Caminho walkable escuro
                    it.fillColor = "#1F2023".toColorInt()
                } else {
                    // Sala clara
                    it.fillColor = "#ECECEC".toColorInt()
                }
                // Não atualiza nenhum campo de cor no painel (seletor removido)
                editor.invalidate()
            }
        }
    }

    private fun setRotationLabel(value: Int) {
        rotationLabel?.text = "$value°"
    }

    private fun setRotationLabelFromProgress() {
        val v = rotationBar?.progress ?: 0
        rotationLabel?.text = "$v°"
    }

    private fun setupRotation() {
        rotationBar?.max = 360
        rotationBar?.setOnSeekBarChangeListener(object : SeekBar.OnSeekBarChangeListener {
            override fun onProgressChanged(seekBar: SeekBar?, progress: Int, fromUser: Boolean) {
                setRotationLabel(progress)
                if (!fromUser || isProgrammatic) return
                val obj = editor.actions.firstOrNull { (it is Action.Shape && it.selected) || (it is Action.Poi && it.selected) }
                when (obj) {
                    is Action.Shape -> { obj.rotation = progress.toFloat(); editor.invalidate() }
                    is Action.Poi -> { obj.rotation = progress.toFloat(); editor.invalidate() }
                    else -> {}
                }
            }
            override fun onStartTrackingTouch(seekBar: SeekBar?) {}
            override fun onStopTrackingTouch(seekBar: SeekBar?) {}
        })
    }

    // ===== MapEditorView callbacks =====
    override fun onShapeSelected(props: ShapeProps) {
        val obj = editor.actions.firstOrNull { (it is Action.Shape && it.selected) || (it is Action.Poi && it.selected) }
            ?: return
        val meta = metaStore.getOrPut(obj) {
            Meta(
                nome = when (obj) {
                    is Action.Shape -> obj.nome
                    else -> ""
                },
                corHex = if (obj is Action.Shape) String.format("#%06X", (0xFFFFFF and obj.fillColor)) else "#D9D9D9"
            )
        }

        isProgrammatic = true
        edtNome.setText(meta.nome)
        // Não exibe/atualiza campo de cor
        // Posição agora exibida em metros
        edtPosX.setText(fmt(editor.pxToMeters(props.x)))
        edtPosY.setText(fmt(editor.pxToMeters(props.y)))
        // Largura/altura exibidas em metros
        edtWidth.setText(fmt(editor.pxToMeters(props.width)))
        edtHeight.setText(fmt(editor.pxToMeters(props.height)))
        // Rotação
        rotationBar?.progress = props.rotation.toInt().coerceIn(0, rotationBar.max)
        setRotationLabelFromProgress()

        // Mostrar/ocultar seções conforme o tipo selecionado
        when (obj) {
            is Action.Poi -> {
                layoutStartQR?.visibility = View.VISIBLE
                switchIsStartQR?.isChecked = obj.isStartQR
                layoutIsWalkable?.visibility = View.GONE
                // Oculta campo de nome para POI
                edtNome?.visibility = View.GONE
            }
            is Action.Shape -> {
                layoutIsWalkable?.visibility = View.VISIBLE
                checkboxIsWalkable?.isChecked = obj.isWalkable
                layoutStartQR?.visibility = View.GONE
                // Exibe nome para Shape
                edtNome?.visibility = View.VISIBLE
            }
            else -> {
                layoutStartQR?.visibility = View.GONE
                layoutIsWalkable?.visibility = View.GONE
                edtNome?.visibility = View.GONE
            }
        }

        // Não atualiza preview de cor
        painel.visibility = View.VISIBLE
        // Reassert Z-order when showing
        painel.bringToFront()
        try { painel.elevation = 1000f } catch (_: Throwable) {}
        isProgrammatic = false
    }

    override fun onShapeDeselected() {
        painel.visibility = View.GONE
        layoutStartQR?.visibility = View.GONE
        layoutIsWalkable?.visibility = View.GONE
    }

    // ===== Field handlers =====
    private fun setupFieldHandlers() {
        applyOnEdit(edtPosX) { pushPosition() }
        applyOnEdit(edtPosY) { pushPosition() }
        applyOnEdit(edtWidth) { pushSize() }
        applyOnEdit(edtHeight) { pushSize() }
        applyOnEdit(edtNome) { saveMeta() }
        // Removido: applyOnEdit(edtCor) pois seletor/edição de cor foi desativado
    }

    private fun pushPosition() {
        if (isProgrammatic) return
        val obj = editor.actions.firstOrNull { (it is Action.Shape && it.selected) || (it is Action.Poi && it.selected) } ?: return

        // Entradas em metros -> converter para pixels
        val xMeters = edtPosX.text.toString().toFloatOrNull()
        val yMeters = edtPosY.text.toString().toFloatOrNull()
        val xPx = xMeters?.let { editor.metersToPx(it) }
        val yPx = yMeters?.let { editor.metersToPx(it) }

        when(obj) {
            is Action.Shape -> {
                val width = obj.end.x - obj.start.x
                val height = obj.end.y - obj.start.y
                if (xPx != null) obj.start.x = xPx
                if (yPx != null) obj.start.y = yPx
                obj.end.x = obj.start.x + width
                obj.end.y = obj.start.y + height
            }
            is Action.Poi -> {
                if (xPx != null) obj.x = xPx
                if (yPx != null) obj.y = yPx
            }
            is Action.BrushStroke -> {}
            is Action.Text -> {}
        }
        editor.invalidate()
    }

    private fun pushSize() {
        if (isProgrammatic) return
        val obj = editor.actions.firstOrNull { (it is Action.Shape && it.selected) || (it is Action.Poi && it.selected) } ?: return

        // Entradas são em metros; converter para pixels
        val wMeters = edtWidth.text.toString().toFloatOrNull()
        val hMeters = edtHeight.text.toString().toFloatOrNull()
        val wPx = wMeters?.let { editor.metersToPx(it) }
        val hPx = hMeters?.let { editor.metersToPx(it) }

        when(obj) {
            is Action.Shape -> {
                obj.end.x = obj.start.x + (wPx ?: (obj.end.x - obj.start.x))
                obj.end.y = obj.start.y + (hPx ?: (obj.end.y - obj.start.y))
            }
            is Action.Poi -> {
                obj.width = wPx ?: obj.width
                obj.height = hPx ?: obj.height
            }
            is Action.BrushStroke -> {} // nada
            is Action.Text -> {}
        }
        editor.invalidate()
    }

    private fun saveMeta() {
        if (isProgrammatic) return
        val obj = editor.actions.firstOrNull { (it is Action.Shape && it.selected) || (it is Action.Poi && it.selected) } ?: return
        val m = metaStore.getOrPut(obj) { Meta() }
        m.nome = edtNome.text.toString()
        // Não salva mais hex manual do painel (seletor removido)
        // m.corHex = edtCor.text.toString().ifBlank { "#D9D9D9" }
        when (obj) {
            is Action.Shape -> { obj.nome = m.nome }
            is Action.Poi -> { /* POI não possui nome/descrição */ }
            else -> {}
        }
    }

    private fun fmt(v: Float): String {
        return if (v % 1.0 == 0.0) v.toInt().toString()
        else String.format(Locale.US, "%.2f", v)
    }

    private fun applyOnEdit(edit: EditText, action: () -> Unit) {
        edit.imeOptions = EditorInfo.IME_ACTION_DONE
        edit.isSingleLine = true

        edit.setOnFocusChangeListener { _, hasFocus ->
            if (!hasFocus && !isProgrammatic) action()
        }
        edit.setOnEditorActionListener { v, actionId, event ->
            val imeDone = actionId == EditorInfo.IME_ACTION_DONE ||
                    (event?.keyCode == KeyEvent.KEYCODE_ENTER && event.action == KeyEvent.ACTION_UP)
            if (imeDone && !isProgrammatic) {
                action()
                val imm = v.context.getSystemService(android.content.Context.INPUT_METHOD_SERVICE) as android.view.inputmethod.InputMethodManager
                val token = v.windowToken
                if (token != null) {
                    imm.hideSoftInputFromWindow(token, 0)
                }
                v.clearFocus()
                true
            } else false
        }
    }
}
